İşte Silkroad Online atmosferini yansıtan zengin bir harita üretim modülü için Three.js fonksiyonları:

1. Prosedürel Çöl Kumu Dokusu ve Antik İpek Yolu Taş Kaplama Dokusu:

```javascript
function createSandTexture() {
    const texture = new THREE.CanvasTexture(createSandCanvas());
    texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
    texture.repeat.set(10, 10);
    return texture;
}

function createSandCanvas() {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    canvas.width = 256;
    canvas.height = 256;

    const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
    gradient.addColorStop(0, '#fdd835');
    gradient.addColorStop(0.5, '#f9c74f');
    gradient.addColorStop(1, '#fdd835');

    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    return canvas;
}

function createCobblestoneTexture() {
    const texture = new THREE.CanvasTexture(createCobblestoneCanvas());
    texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
    texture.repeat.set(10, 10);
    return texture;
}

function createCobblestoneCanvas() {
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    canvas.width = 256;
    canvas.height = 256;

    const gradient = ctx.createLinearGradient(0, 0, 0, canvas.height);
    gradient.addColorStop(0, '#8b4513');
    gradient.addColorStop(0.5, '#a0522d');
    gradient.addColorStop(1, '#8b4513');

    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    return canvas;
}
```

