function createHotanFortressAndCaravanserai() {
    const geometry = new THREE.BoxGeometry(10, 20, 5);
    const material = new THREE.MeshBasicMaterial({ color: 0x8b4513 });
    const fortress = new THREE.Mesh(geometry, material);

    fortress.position.set(0, 10, 0);

    const caravan = new THREE.BoxGeometry(5, 5, 2);
    const caravanMaterial = new THREE.MeshBasicMaterial({ color: 0x8b4513 });
    const caravanMesh = new THREE.Mesh(caravan, caravanMaterial);

    caravanMesh.position.set(0, 2, 0);

    return { fortress, caravanMesh };
